const I18N_RULES = [["^(\\d+) gruppe$", "\\1 group", "^(\\d+) group$", "\\1 gruppe"], ["^(\\d+) grupper$", "\\1 groups", "^(\\d+) groups$", "\\1 grupper"], ["^(\\d+) handling$", "\\1 action", "^(\\d+) action$", "\\1 handling"], ["^(\\d+) handlinger$", "\\1 actions", "^(\\d+) actions$", "\\1 handlinger"], ["^(.+) \\+ (\\d+) mer$", "\\1 + \\2 more", "^(.+) \\+ (\\d+) more$", "\\1 + \\2 mer"]];
